import Image from "next/image";
import { equipments } from "@/data/equipments";
import { CheckCircle } from "lucide-react";

export const metadata = {
    title: "Advanced Lab Equipment | Sukra House of Diagnostic",
    description: "Explore our state-of-the-art laboratory equipment ensuring precise and rapid diagnostic results.",
};

export default function EquipmentsPage() {
    return (
        <div className="bg-gray-50 min-h-screen">
            {/* Header with Gradient */}
            <div className="bg-gradient-to-r from-medical-teal-900 to-medical-teal-700 pt-32 pb-24 text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-96 h-96 bg-white opacity-5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                <div className="absolute bottom-0 left-0 w-64 h-64 bg-medical-orange-500 opacity-10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>

                <div className="container mx-auto px-4 text-center relative z-10">
                    <h4 className="text-medical-orange-400 font-bold tracking-wider uppercase text-sm mb-3">Technology</h4>
                    <h1 className="text-4xl md:text-5xl font-extrabold text-white mb-6 drop-shadow-md">State-of-the-Art Technology</h1>
                    <div className="w-24 h-1.5 bg-medical-orange-500 mx-auto rounded-full mb-8"></div>
                    <p className="text-teal-50 text-lg md:text-xl max-w-2xl mx-auto font-medium leading-relaxed">
                        We invest in the latest automated diagnostic systems to ensure 100% accuracy and faster turnaround times.
                    </p>
                </div>
            </div>

            <div className="container mx-auto px-4 py-16 -mt-10 relative z-20">
                <div className="grid md:grid-cols-2 lg:grid-cols-2 gap-8">
                    {equipments.map((item) => (
                        <div key={item.id} className="bg-white rounded-3xl overflow-hidden shadow-lg border border-gray-100 hover:shadow-2xl transition-all duration-300 group flex flex-col md:flex-row">
                            <div className="md:w-2/5 bg-gray-100 relative h-64 md:h-auto">
                                {/* Image Placeholder */}
                                <div className="absolute inset-0 flex items-center justify-center text-gray-400 bg-gray-200">
                                    <svg className="w-16 h-16 opacity-50" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 3v2m6-2v2M9 19v2m6-2v2M5 9H3m2 6H3m18-6h-2m2 6h-2M7 19h10a2 2 0 002-2V7a2 2 0 00-2-2H7a2 2 0 00-2 2v10a2 2 0 002 2zM9 9h6v6H9V9z" /></svg>
                                </div>
                            </div>
                            <div className="p-8 md:w-3/5 flex flex-col justify-center">
                                <div className="mb-4">
                                    <span className="bg-medical-teal-50 text-medical-teal-700 text-xs font-bold px-3 py-1 rounded-full uppercase tracking-wider">{item.category}</span>
                                </div>
                                <h3 className="text-2xl font-bold text-gray-900 mb-2 group-hover:text-medical-teal-600 transition-colors">{item.name}</h3>
                                <p className="text-sm text-gray-500 font-medium mb-4 flex items-center gap-2">
                                    <CheckCircle size={16} className="text-medical-orange-500" />
                                    {item.brand}
                                </p>
                                <p className="text-gray-600 leading-relaxed text-sm">
                                    {item.description}
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

import Image from "next/image";
import { team } from "@/data/team";

export const metadata = {
    title: "Our Team | Sukra House of Diagnostic",
    description: "Meet the dedicated leadership and management team behind Sukra House of Diagnostic.",
};

export default function TeamPage() {
    return (
        <div className="bg-gray-50 min-h-screen">
            {/* Header with Gradient */}
            <div className="bg-gradient-to-r from-medical-teal-900 to-medical-teal-700 pt-32 pb-24 text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-96 h-96 bg-white opacity-5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                <div className="absolute bottom-0 left-0 w-64 h-64 bg-medical-orange-500 opacity-10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>

                <div className="container mx-auto px-4 text-center relative z-10">
                    <h4 className="text-medical-orange-400 font-bold tracking-wider uppercase text-sm mb-3">Leadership</h4>
                    <h1 className="text-4xl md:text-5xl font-extrabold text-white mb-6 drop-shadow-md">Our Leadership Team</h1>
                    <div className="w-24 h-1.5 bg-medical-orange-500 mx-auto rounded-full mb-8"></div>
                    <p className="text-teal-50 text-lg md:text-xl max-w-2xl mx-auto font-medium leading-relaxed">
                        Guided by visionaries dedicated to excellence in healthcare and diagnostic services.
                    </p>
                </div>
            </div>

            <div className="container mx-auto px-4 py-16 -mt-10 relative z-20">
                <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-8">
                    {team.map((member) => (
                        <div key={member.id} className="bg-white rounded-3xl overflow-hidden shadow-lg border border-gray-100 hover:shadow-2xl transition-all duration-300 group">
                            <div className="h-64 bg-gray-200 relative overflow-hidden">
                                <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                                    {/* Placeholder icon until real images are used */}
                                    <svg className="w-20 h-20" fill="currentColor" viewBox="0 0 24 24"><path d="M12 12c2.21 0 4-1.79 4-4s-1.79-4-4-4-4 1.79-4 4 1.79 4 4 4zm0 2c-2.67 0-8 1.34-8 4v2h16v-2c0-2.66-5.33-4-8-4z" /></svg>
                                </div>
                            </div>
                            <div className="p-6 text-center">
                                <h3 className="text-xl font-bold text-gray-900 mb-1 group-hover:text-medical-teal-600 transition-colors">{member.name}</h3>
                                <p className="text-medical-orange-500 font-bold text-sm uppercase tracking-wide mb-3">{member.role}</p>
                                <p className="text-gray-500 text-sm leading-relaxed">
                                    {member.bio}
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}

import Link from "next/link";
import { getPackages } from "@/app/lib/package-actions";
import { getTests } from "@/app/lib/test-actions";
import { Check, ArrowRight, Tag } from "lucide-react";

export const metadata = {
    title: "Health Packages & Tests | Sukra House of Diagnostic",
    description: "Affordable health packages and diagnostic tests with transparent pricing.",
};

export default async function PackagesPage() {
    const packages = await getPackages();
    const tests = await getTests(); // For the common tests pricing table

    return (
        <div className="bg-gray-50 min-h-screen">
            {/* Header with Gradient */}
            <div className="bg-gradient-to-r from-medical-teal-900 to-medical-teal-700 pt-32 pb-24 text-white relative overflow-hidden">
                <div className="absolute top-0 right-0 w-96 h-96 bg-white opacity-5 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
                <div className="absolute bottom-0 left-0 w-64 h-64 bg-medical-orange-500 opacity-10 rounded-full blur-3xl translate-y-1/2 -translate-x-1/2"></div>

                <div className="container mx-auto px-4 text-center relative z-10">
                    <h4 className="text-medical-orange-400 font-bold tracking-wider uppercase text-sm mb-3">Pricing & Plans</h4>
                    <h1 className="text-4xl md:text-5xl font-extrabold text-white mb-6 drop-shadow-md">Affordable Health Packages</h1>
                    <div className="w-24 h-1.5 bg-medical-orange-500 mx-auto rounded-full mb-8"></div>
                    <p className="text-teal-50 text-lg md:text-xl max-w-2xl mx-auto font-medium leading-relaxed">
                        Transparent pricing for all your diagnostic needs. Choose a package that suits you best.
                    </p>
                </div>
            </div>

            <div className="container mx-auto px-4 py-16 -mt-10 relative z-20">

                {/* Packages Grid */}
                <h2 className="text-2xl font-bold text-gray-800 mb-8 border-l-4 border-medical-orange-500 pl-4">Exclusive Health Packages</h2>
                {packages.length === 0 ? (
                    <div className="text-center py-12 bg-white rounded-3xl shadow-sm border border-gray-100">
                        <p className="text-gray-500">No packages available at the moment.</p>
                    </div>
                ) : (
                    <div className="grid md:grid-cols-2 lg:grid-cols-2 gap-8 mb-20">
                        {packages.map((pkg: any) => {
                            // Calculate discount percentage if original price exists
                            const discountPercentage = pkg.originalPrice && pkg.price
                                ? Math.round(((pkg.originalPrice - pkg.price) / pkg.originalPrice) * 100)
                                : 0;

                            return (
                                <div key={pkg.id} className="bg-white rounded-3xl overflow-hidden shadow-lg border border-gray-100 hover:shadow-2xl transition-all duration-300 relative group flex flex-col">
                                    {discountPercentage > 0 && (
                                        <div className="absolute top-0 right-0 bg-medical-orange-500 text-white text-xs font-bold px-4 py-2 rounded-bl-2xl z-10 flex items-center gap-1">
                                            <Tag size={12} /> {discountPercentage}% OFF
                                        </div>
                                    )}

                                    <div className="p-8 flex-grow">
                                        <h3 className="text-2xl font-bold text-medical-teal-700 mb-2">{pkg.name}</h3>
                                        <p className="text-gray-600 mb-6 text-sm">{pkg.description}</p>

                                        <div className="bg-gray-50 rounded-2xl p-6 mb-6">
                                            <h4 className="font-bold text-gray-800 text-sm uppercase tracking-wider mb-4 border-b border-gray-200 pb-2">What's Included</h4>
                                            <ul className="space-y-3">
                                                {pkg.tests && pkg.tests.length > 0 ? (
                                                    pkg.tests.map((test: any) => (
                                                        <li key={test.id} className="flex items-start gap-3 text-sm text-gray-700">
                                                            <span className="bg-teal-100 text-medical-teal-600 rounded-full p-0.5 mt-0.5"><Check size={12} strokeWidth={3} /></span>
                                                            {test.name}
                                                        </li>
                                                    ))
                                                ) : (
                                                    <li className="text-sm text-gray-400 italic">No specific tests listed.</li>
                                                )}
                                            </ul>
                                        </div>
                                    </div>

                                    <div className="px-8 pb-8 pt-0 mt-auto">
                                        <div className="flex items-end gap-3 mb-6">
                                            <span className="text-4xl font-extrabold text-gray-900">Rs. {pkg.price}</span>
                                            {pkg.originalPrice && (
                                                <span className="text-lg text-gray-400 line-through font-medium mb-1.5">Rs. {pkg.originalPrice}</span>
                                            )}
                                        </div>
                                        <Link href="/appointment" className="block w-full text-center bg-medical-teal-600 hover:bg-medical-teal-700 text-white font-bold py-4 rounded-xl transition-all shadow-md hover:shadow-lg hover:-translate-y-0.5">
                                            Book Now
                                        </Link>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Individual Tests Section */}
                <h2 className="text-2xl font-bold text-gray-800 mb-8 border-l-4 border-medical-teal-500 pl-4">Common Tests Pricing</h2>
                <div className="bg-white rounded-3xl shadow-sm border border-gray-100 overflow-hidden">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="bg-gray-50 border-b border-gray-200">
                                    <th className="p-6 font-bold text-gray-600 text-sm uppercase tracking-wider">Test Name</th>
                                    <th className="p-6 font-bold text-gray-600 text-sm uppercase tracking-wider">Category</th>
                                    <th className="p-6 font-bold text-gray-600 text-sm uppercase tracking-wider text-right">Price (NPR)</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-100">
                                {tests.length === 0 ? (
                                    <tr>
                                        <td colSpan={3} className="p-6 text-center text-gray-500">No tests listed yet.</td>
                                    </tr>
                                ) : (
                                    tests.slice(0, 15).map((test) => ( // limit to 15 for brevity
                                        <tr key={test.id} className="hover:bg-teal-50/30 transition-colors">
                                            <td className="p-6 font-medium text-gray-900">{test.name}</td>
                                            <td className="p-6">
                                                <span className="bg-gray-100 text-gray-600 text-xs px-3 py-1 rounded-full font-medium">{test.category}</span>
                                            </td>
                                            <td className="p-6 text-right font-bold text-medical-teal-600">Rs. {test.price}</td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                    {tests.length > 15 && (
                        <div className="bg-gray-50 p-6 text-center border-t border-gray-100">
                            <p className="text-sm text-gray-500 mb-4">Displaying top 15 tests. We have {tests.length} tests available.</p>
                            <Link href="/contact" className="inline-flex items-center gap-2 text-medical-teal-600 font-bold hover:text-medical-orange-500 transition-colors">
                                Contact Us for Full Price List <ArrowRight size={16} />
                            </Link>
                        </div>
                    )}
                </div>

            </div>
        </div>
    );
}

import { Metadata } from 'next';
import ServiceCard from '@/components/ServiceCard';
import { Microscope, Beaker, Droplet, Activity, Dna, FileText } from 'lucide-react';

export const metadata: Metadata = {
    title: 'Our Services | Sukra House of Diagnostic',
    description: 'Comprehensive diagnostic services including Pathology, Biochemistry, Hematology, and more.',
};

import { getTests } from '@/app/lib/test-actions';

export default async function ServicesPage() {
    const tests = await getTests();
    const services = [
        {
            title: "Pathology",
            description: "Histopathology and Cytopathology services for accurate cancer and tissue diagnosis.",
            icon: <Microscope size={24} />
        },
        {
            title: "Biochemistry",
            description: "Liver function, Kidney function, Lipid profile, and other routine chemical analysis.",
            icon: <Beaker size={24} />
        },
        {
            title: "Hematology",
            description: "CBC, Coagulation profile, and blood disorder diagnosis.",
            icon: <Droplet size={24} />
        },
        {
            title: "Microbiology",
            description: "Culture and sensitivity tests for bacterial and fungal infections.",
            icon: <Dna size={24} />
        },
        {
            title: "Serology & Immunology",
            description: "Hormone tests, Thyroid profile, and infectious disease markers.",
            icon: <Activity size={24} />
        },
        {
            title: "Health Packages",
            description: "Whole body checkup packages tailored for different age groups.",
            icon: <FileText size={24} />
        }
    ];

    return (
        <div className="bg-white">
            {/* Header */}
            <section className="bg-medical-blue-50 py-16">
                <div className="container mx-auto px-4 text-center">
                    <h1 className="text-4xl font-bold text-gray-900 mb-4">Our Services</h1>
                    <p className="text-gray-600 max-w-2xl mx-auto">
                        Using the latest technology to deliver precise results for a wide range of medical tests.
                    </p>
                </div>
            </section>

            {/* Services Grid */}
            <section className="py-20">
                <div className="container mx-auto px-4">
                    <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
                        {services.map((service, index) => (
                            <ServiceCard
                                key={index}
                                title={service.title}
                                description={service.description}
                                icon={service.icon}
                            />
                        ))}
                    </div>
                </div>
        </div>
            </section >

        {/* Test Menu Section */ }
        < section className = "bg-gray-50 py-20 border-t border-gray-100" >
            <div className="container mx-auto px-4">
                <div className="text-center mb-12">
                    <h2 className="text-3xl font-bold text-gray-900 mb-4">Common Lab Tests</h2>
                    <p className="text-gray-600 max-w-2xl mx-auto">
                        Transparent pricing for our most frequently requested diagnostic tests.
                    </p>
                </div>

                <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden max-w-4xl mx-auto">
                    <div className="overflow-x-auto">
                        <table className="w-full text-left">
                            <thead className="bg-medical-teal-50 border-b border-medical-teal-100">
                                <tr>
                                    <th className="px-6 py-4 font-bold text-medical-teal-800">Test Name</th>
                                    <th className="px-6 py-4 font-bold text-medical-teal-800">Category</th>
                                    <th className="px-6 py-4 font-bold text-medical-teal-800">Turnaround Time</th>
                                    <th className="px-6 py-4 font-bold text-medical-teal-800 text-right">Price</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-gray-50">
                                {tests.length === 0 ? (
                                    <tr>
                                        <td colSpan={4} className="px-6 py-8 text-center text-gray-400">
                                            No specific tests listed yet. Please contact us for a full price list.
                                        </td>
                                    </tr>
                                ) : (
                                    tests.map((test: any) => (
                                        <tr key={test.id} className="hover:bg-gray-50 transition-colors">
                                            <td className="px-6 py-4">
                                                <div className="font-medium text-gray-900">{test.name}</div>
                                                {test.description && <div className="text-xs text-gray-500 mt-0.5">{test.description}</div>}
                                            </td>
                                            <td className="px-6 py-4">
                                                <span className="text-xs font-medium px-2 py-1 rounded-full bg-blue-50 text-blue-700">
                                                    {test.category}
                                                </span>
                                            </td>
                                            <td className="px-6 py-4 text-sm text-gray-500">
                                                {test.tat || '24 Hours'}
                                            </td>
                                            <td className="px-6 py-4 text-right font-bold text-gray-900">
                                                {test.discountPrice ? (
                                                    <div className="flex flex-col items-end">
                                                        <span className="text-green-600">Rs. {test.discountPrice}</span>
                                                        <span className="text-gray-400 text-xs line-through">Rs. {test.price}</span>
                                                    </div>
                                                ) : (
                                                    <span>Rs. {test.price}</span>
                                                )}
                                            </td>
                                        </tr>
                                    ))
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
            </section >

        {/* CTA */ }
        < section className = "bg-medical-blue-700 py-16 text-white text-center" >
            <div className="container mx-auto px-4">
                <h2 className="text-3xl font-bold mb-6">Need a Test?</h2>
                <p className="text-blue-100 mb-8">
                    Book an appointment online or visit our center for a walk-in test.
                </p>
                <a href="/appointment" className="bg-medical-green-500 hover:bg-medical-green-600 text-white px-8 py-3 rounded-full font-bold transition">
                    Book Now
                </a>
            </div>
            </section >
        </div >
    );
}

import { getPaginatedBookings, fetchCollectors } from "@/app/lib/booking-actions";
import BookingRow from "@/components/admin/BookingRow";
import AddBookingModal from "@/components/admin/AddBookingModal";
import AutoRefresh from "@/components/AutoRefresh";
import PaginationControls from "@/components/admin/PaginationControls";
import BookingFilters from "@/components/admin/BookingFilters";

export const metadata = {
    title: "Manage Bookings | Admin Dashboard",
};

interface PageProps {
    searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}

export default async function BookingsPage({ searchParams }: PageProps) {
    const resolvedSearchParams = await searchParams;
    const page = Number(resolvedSearchParams?.page) || 1;
    const limit = Number(resolvedSearchParams?.limit) || 10;
    const search = resolvedSearchParams?.search as string | undefined;
    const status = resolvedSearchParams?.status as string | undefined;
    const type = resolvedSearchParams?.type as string | undefined;

    const { bookings, metadata: paginationMetadata } = await getPaginatedBookings(page, limit, search, status, type);
    const collectors = await fetchCollectors();

    return (
        <div className="space-y-6">
            <AutoRefresh intervalMs={5000} />
            <div className="flex justify-between items-center">
                <h1 className="text-2xl font-bold text-gray-800">Booking Management</h1>
                <AddBookingModal />
            </div>

            {/* Search and Filters */}
            <BookingFilters />

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="overflow-x-auto min-h-[400px]">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 border-b border-gray-200">
                            <tr className="text-gray-500 text-sm uppercase">
                                <th className="px-6 py-4 font-medium">ID</th>
                                <th className="px-6 py-4 font-medium">Patient</th>
                                <th className="px-6 py-4 font-medium">Test Type</th>
                                <th className="px-6 py-4 font-medium">Date</th>
                                <th className="px-6 py-4 font-medium">Status / Timeline</th>
                                <th className="px-6 py-4 font-medium">Sample ID</th>
                                <th className="px-6 py-4 font-medium">Source</th>
                                <th className="px-6 py-4 font-medium text-center">Report</th>
                                <th className="px-6 py-4 font-medium text-right">Actions</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100">
                            {bookings.map((booking: any) => (
                                <BookingRow
                                    key={booking.id}
                                    booking={booking}
                                    collectors={collectors}
                                />
                            ))}
                            {bookings.length === 0 && (
                                <tr>
                                    <td colSpan={9} className="text-center py-10 text-gray-500">
                                        No bookings found matching your criteria.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
                <div className="px-4 border-t border-gray-100">
                    <PaginationControls
                        totalItems={paginationMetadata.total}
                        currentPage={paginationMetadata.page}
                        totalPages={paginationMetadata.totalPages}
                        itemsPerPage={paginationMetadata.limit}
                    />
                </div>
            </div>
        </div>
    );
}

import { getDoctors } from '@/app/lib/doctor-actions';
import DoctorFormToggle from '@/components/admin/DoctorFormToggle';
import DoctorCard from '@/components/DoctorCard';
import { User, Plus } from 'lucide-react';
import Image from 'next/image';

import DoctorSearch from '@/components/admin/DoctorSearch';

export default async function AdminDoctorsPage(props: { searchParams: Promise<{ query?: string }> }) {
    const searchParams = await props.searchParams;
    const query = searchParams?.query || '';
    const doctors = await getDoctors(query);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">Doctors Management</h1>
                    <p className="text-gray-500 text-sm mt-1">Manage doctor profiles and details shown on the website</p>
                </div>
                <div className="flex items-center gap-4">
                    <DoctorSearch />
                    <div className="bg-medical-teal-50 px-4 py-2 rounded-lg border border-medical-teal-100">
                        <span className="text-sm font-bold text-medical-teal-700">Total: {doctors.length}</span>
                    </div>
                    {/* Add Doctor Button Component (Client-side trigger) */}
                    <DoctorFormToggle />
                </div>
            </div>



            {doctors.length === 0 ? (
                <div className="text-center py-20 bg-gray-50 rounded-xl border border-gray-200 border-dashed">
                    <div className="bg-white p-4 rounded-full w-16 h-16 flex items-center justify-center mx-auto shadow-sm mb-4">
                        <User className="text-gray-300" size={32} />
                    </div>
                    <h3 className="text-gray-900 font-bold text-lg">No Doctors Found</h3>
                    <p className="text-gray-500 text-sm max-w-sm mx-auto mt-2">Start by adding a new doctor to display on the website.</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {doctors.map((doctor) => (
                        <div key={doctor.id} className="relative group">
                            {/* Reusing Frontend Card for consistency, but wrapping with Edit functionality */}
                            <DoctorCard
                                id={doctor.id as any} // Cast ID if needed (card expects number but schema is string uuid)
                                name={doctor.name}
                                specialty={doctor.specialty}
                                education={doctor.education}
