export async function updateUserRole(formData: FormData) {
    try {
        const session = await auth();
        if (!session?.user || (session.user as any).role !== 'ADMIN') {
            return { message: 'Unauthorized' };
        }

        const userId = formData.get('userId') as string;
        const newRole = formData.get('role') as string;

        if (!userId || !newRole) {
            return { message: 'Missing fields' };
        }

        // Prevent changing own role essentially locking oneself out if demoting
        if (userId === (session.user as any).id) {
            return { message: 'Cannot change your own role.' };
        }

        await prisma.user.update({
            where: { id: userId },
            data: { role: newRole },
        });

        revalidatePath('/admin/permissions');
        return { message: 'User role updated successfully.' };
    } catch (error) {
        console.error('Failed to update user role:', error);
        return { message: 'Database Error: Failed to update role.' };
    }
}

export async function updateUser(prevState: any, formData: FormData) {
    try {
        const session = await auth();
        if (!session?.user || (session.user as any).role !== 'ADMIN') {
            return { message: 'Unauthorized' };
        }

        const id = formData.get('id') as string;
        const name = formData.get('name') as string;
        const email = formData.get('email') as string;
        const role = formData.get('role') as string;
        const groupId = formData.get('groupId') as string;
        const password = formData.get('password') as string;

        if (!id || !name || !email || !role) {
            return { message: 'Missing required fields.' };
        }

        // Check if email is taken by another user
        const existingUser = await prisma.user.findFirst({
            where: {
                email,
                NOT: { id }
            }
        });

        if (existingUser) {
            return { message: 'Email already in use by another user.' };
        }

        const updateData: any = {
            name,
            email,
            role,
            groupId: groupId || null,
        };

        if (password && password.length >= 6) {
            const hashedPassword = await bcrypt.hash(password, 10);
            updateData.password = hashedPassword;
        }

        await prisma.user.update({
            where: { id },
            data: updateData,
        });

        revalidatePath('/admin/users');
        return { message: 'Success! User updated.' };
    } catch (error) {
        console.error('Failed to update user:', error);
        return { message: 'Database Error: Failed to update user.' };
    }
}

import type { NextAuthConfig } from 'next-auth';

export const authConfig = {
    pages: {
        signIn: '/login',
        error: '/login', // Error code passed in query string as ?error=
    },
    callbacks: {
        authorized({ auth, request: { nextUrl } }) {
            const isLoggedIn = !!auth?.user;
            const isAdminSection = nextUrl.pathname.startsWith('/admin');

            if (isAdminSection) {
                if (isLoggedIn && (auth.user as any).role === 'ADMIN') return true;
                return false; // Redirect unauthenticated or non-admin users to login page
            }

            const isCollectorSection = nextUrl.pathname.startsWith('/collector');
            if (isCollectorSection) {
                if (isLoggedIn && (auth.user as any).role === 'COLLECTOR') return true;
                return false; // Redirect unauthenticated or non-collector users to login page
            }
            return true;
        },
        jwt({ token, user, trigger, session }) {
            if (user) {
                token.id = user.id;
                // param matches the Prisma User model role
                token.role = (user as any).role;
            }
            return token;
        },
        session({ session, token }) {
            if (token) {
                (session.user as any).id = token.id;
                (session.user as any).role = token.role;
            }
            return session;
        }
    },
    providers: [], // Add providers with an empty array for now
} satisfies NextAuthConfig;

