export default function Navbar() {
    const [isOpen, setIsOpen] = useState(false);
    const [isAboutOpen, setIsAboutOpen] = useState(false);
    const [isScrolled, setIsScrolled] = useState(false);

    const [status, setStatus] = useState<{ isOpen: boolean; text: string; color: string }>({ isOpen: false, text: "", color: "" });

    // Handle Scroll for shrinking logic
    // Handle Scroll for shrinking logic
    useEffect(() => {
        let lastScrollY = window.scrollY;
        let ticking = false;

        const handleScroll = () => {
            if (!ticking) {
                window.requestAnimationFrame(() => {
                    const currentScrollY = window.scrollY;

                    // Simple hysteresis to prevent flickering
                    if (currentScrollY > 60) {
                        setIsScrolled(true);
                    } else if (currentScrollY < 40) {
                        setIsScrolled(false);
                    }

                    lastScrollY = currentScrollY;
                    ticking = false;
                });
                ticking = true;
            }
        };

        window.addEventListener("scroll", handleScroll);

        // Calculate Status
        const checkStatus = () => {
            const now = new Date();
            const day = now.getDay(); // 0 is Sunday
            const hour = now.getHours();

            // Sunday (0) to Friday (5): 8:00 - 19:00
            // Saturday (6): 8:00 - 15:00

            let isOpen = false;

            if (day === 6) { // Saturday
                isOpen = hour >= 8 && hour < 15;
            } else { // Sun - Fri
                isOpen = hour >= 8 && hour < 19;
            }

            if (isOpen) {
                setStatus({ isOpen: true, text: "Open Now", color: "bg-green-500" });
            } else {
                setStatus({ isOpen: false, text: "Closed Now", color: "bg-red-500" });
            }
        };

        checkStatus();
        const interval = setInterval(checkStatus, 60000); // Update every minute

        return () => {
            window.removeEventListener("scroll", handleScroll);
            clearInterval(interval);
        };
    }, []);

    return (
