'use client';

import { useRouter, usePathname, useSearchParams } from 'next/navigation';
import { useState, useEffect } from 'react';
import { Search, Filter, X } from 'lucide-react';
import { useDebounce } from 'use-debounce';

export default function BookingFilters() {
    const router = useRouter();
    const pathname = usePathname();
    const searchParams = useSearchParams();

    // Initial state from URL
    const [searchTerm, setSearchTerm] = useState(searchParams.get('search') || '');
    const [status, setStatus] = useState(searchParams.get('status') || 'ALL');
    const [type, setType] = useState(searchParams.get('type') || 'ALL');
    const [showFilters, setShowFilters] = useState(false);

    // Debounce search to avoid too many requests
    const [debouncedSearch] = useDebounce(searchTerm, 500);

    // Effect to update URL when fields change
    useEffect(() => {
        const params = new URLSearchParams(searchParams);

        // Reset page on filter change
        params.set('page', '1');

        if (debouncedSearch) {
            params.set('search', debouncedSearch);
        } else {
            params.delete('search');
        }

        if (status && status !== 'ALL') {
            params.set('status', status);
        } else {
            params.delete('status');
        }

        if (type && type !== 'ALL') {
            params.set('type', type);
        } else {
            params.delete('type');
        }

        router.push(`${pathname}?${params.toString()}`);
    }, [debouncedSearch, status, type, pathname, router]);

    // Clear all filters
    const clearFilters = () => {
        setSearchTerm('');
        setStatus('ALL');
        setType('ALL');
        router.push(pathname);
    };

    const hasActiveFilters = status !== 'ALL' || type !== 'ALL' || searchTerm;

    return (
        <div className="space-y-4 mb-6">
            <div className="flex flex-col md:flex-row gap-4 justify-between">
                {/* Search Bar */}
                <div className="relative flex-1 max-w-md">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-4 h-4" />
                    <input
                        type="text"
                        placeholder="Search patient, phone, email, or sample ID..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-medical-teal-500 focus:border-transparent text-sm"
                    />
                </div>

                {/* Filter Toggle & Active Chips */}
                <div className="flex items-center gap-2">
                    <button
                        onClick={() => setShowFilters(!showFilters)}
                        className={`flex items-center gap-2 px-4 py-2 border rounded-lg text-sm font-medium transition-colors ${showFilters || (hasActiveFilters && !showFilters)
                                ? 'bg-medical-teal-50 border-medical-teal-200 text-medical-teal-700'
                                : 'bg-white border-gray-300 text-gray-700 hover:bg-gray-50'
                            }`}
                    >
                        <Filter className="w-4 h-4" />
                        Filters
                    </button>

                    {hasActiveFilters && (
                        <button
                            onClick={clearFilters}
                            className="text-sm text-red-600 hover:text-red-700 font-medium px-2"
                        >
                            Clear
                        </button>
                    )}
                </div>
            </div>

            {/* Expandable Filter Section */}
            {showFilters && (
                <div className="p-4 bg-gray-50 border border-gray-200 rounded-lg grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4 animate-in fade-in slide-in-from-top-2">
                    {/* Status Filter */}
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">Status</label>
                        <select
                            value={status}
                            onChange={(e) => setStatus(e.target.value)}
                            className="w-full p-2 border border-gray-300 rounded-md bg-white text-sm focus:ring-2 focus:ring-medical-teal-500"
                        >
                            <option value="ALL">All Statuses</option>
                            <option value="PENDING">Pending</option>
                            <option value="ASSIGNED">Assigned</option>
                            <option value="COLLECTED">Collected</option>
                            <option value="RECEIVED_AT_LAB">Received at Lab</option>
                            <option value="PROCESSING">Processing</option>
                            <option value="COMPLETED">Completed</option>
                            <option value="CANCELLED">Cancelled</option>
                        </select>
                    </div>

                    {/* Booking Type Filter */}
                    <div className="space-y-1">
                        <label className="text-xs font-semibold text-gray-500 uppercase">Type</label>
                        <select
                            value={type}
                            onChange={(e) => setType(e.target.value)}
                            className="w-full p-2 border border-gray-300 rounded-md bg-white text-sm focus:ring-2 focus:ring-medical-teal-500"
                        >
                            <option value="ALL">All Types</option>
                            <option value="LAB_VISIT">Lab Visit</option>
                            <option value="HOME_COLLECTION">Home Collection</option>
                        </select>
                    </div>
                </div>
            )}
        </div>
    );
}

"use client";

import { useState } from "react";
import { assignBooking, updateBookingStatus, approveAssignment } from "@/app/lib/booking-actions";
import { updateSampleId } from "@/app/lib/report-actions";
import { Loader2, ArrowRight, FileText, Pencil } from "lucide-react";
import { useRouter } from "next/navigation";
import EditBookingModal from "./EditBookingModal";
import BookingDetailsViewModal from "./BookingDetailsViewModal";

export default function BookingRow({ booking, collectors }: { booking: any; collectors: any[] }) {
    const [isLoading, setIsLoading] = useState(false);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [isViewModalOpen, setIsViewModalOpen] = useState(false);
    const router = useRouter();

    const handleAssign = async (collectorId: string) => {
        setIsLoading(true);
        const formData = new FormData();
        formData.append("bookingId", booking.id);
        formData.append("collectorId", collectorId);
        await assignBooking(formData);
        setIsLoading(false);
        router.refresh();
    };

    const handleStatusUpdate = async (status: string) => {
        setIsLoading(true);
        const formData = new FormData();
        formData.append("bookingId", booking.id);
        formData.append("status", status);
        await updateBookingStatus(formData);
        setIsLoading(false);
        router.refresh();
    };

    return (
        <tr className="hover:bg-gray-50 transition-colors">
            <td className="px-6 py-4 text-gray-500 text-sm">
                <button
                    onClick={() => setIsViewModalOpen(true)}
                    className="hover:text-medical-teal-600 hover:underline font-bold transition-colors"
                >
                    #{booking.id.slice(-5).toUpperCase()}
                </button>
            </td>
            <td className="px-6 py-4 font-medium text-gray-900">
                <div>{booking.patientName}</div>
                <div className="text-xs text-gray-500">{booking.phone}</div>
            </td>
            <td className="px-6 py-4 text-gray-600">
                {booking.testType}
                {booking.type === 'HOME_COLLECTION' && (
                    <span className="ml-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-800">
                        Home
                    </span>
                )}
            </td>
            <td className="px-6 py-4 text-gray-600">
                {new Date(booking.date).toLocaleDateString()}
            </td>
            <td className="px-6 py-4">
                <span className={`px-3 py-1 rounded-full text-xs font-bold ${booking.status === 'PENDING' ? 'bg-orange-100 text-orange-700' :
                    booking.status === 'ASSIGNED' ? 'bg-blue-100 text-blue-700' :
                        booking.status === 'COLLECTED' ? 'bg-indigo-100 text-indigo-700' :
                            booking.status === 'RECEIVED_AT_LAB' ? 'bg-purple-100 text-purple-700' :
                                booking.status === 'PROCESSING' ? 'bg-yellow-100 text-yellow-800' :
                                    booking.status === 'COMPLETED' ? 'bg-green-100 text-green-700' :
                                        'bg-gray-100 text-gray-600'
                    }`}>
                    {booking.status}
                </span>
                {booking.assignedTo && (
                    <div className="text-xs text-gray-500 mt-1">
                        Assigned: {booking.assignedTo.name}
                    </div>
                )}

                <div className="text-[10px] text-gray-400 mt-2 space-y-1 font-mono">
                    {booking.requests && booking.requests.length > 0 && booking.requests[0]?.createdAt && (
                        <div>Req: {new Date(booking.requests[0].createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
                    )}
                    {booking.collectedAt && (
                        <div className="text-orange-600 font-medium">Col: {new Date(booking.collectedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
                    )}
                    {booking.receivedAt && (
                        <div className="text-purple-600 font-medium">Drop: {new Date(booking.receivedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>
                    )}
                </div>
            </td>
            <td className="px-6 py-4">
                {/* Sample ID Input */}
                {booking.sampleId ? (
                    <div className="flex items-center gap-2">
                        <span className="text-sm font-mono font-medium text-gray-700 bg-gray-50 px-2 py-1 rounded border border-gray-200">
                            {booking.sampleId}
                        </span>
                        <button
                            onClick={() => setIsEditModalOpen(true)}
                            className="text-gray-400 hover:text-medical-teal-600 transition-colors p-1 rounded-full hover:bg-gray-100"
                        >
                            <Pencil size={12} />
                        </button>
                    </div>
                ) : (
                    <div className="flex items-center gap-2">
                        <form action={async (formData) => {
                            await updateSampleId(formData);
                            router.refresh();
                        }} className="flex items-center gap-1">
                            <input type="hidden" name="bookingId" value={booking.id} />
                            <input
                                type="text"
                                name="sampleId"
                                defaultValue={booking.sampleId || ''}
                                placeholder="Sample ID"
                                className="w-24 text-xs border border-gray-300 rounded px-2 py-1 focus:border-medical-teal-500 focus:ring-1 focus:ring-medical-teal-500"
                            />
                            <button type="submit" className="text-gray-400 hover:text-medical-teal-600">
                                <ArrowRight size={14} />
                            </button>
                        </form>
                        {/* Also allow full edit if needed even before Sample ID is set? Maybe not necessary but good for UX */}
                        <button
                            onClick={() => setIsEditModalOpen(true)}
                            className="text-gray-300 hover:text-medical-teal-600 transition-colors p-1 rounded-full hover:bg-gray-100"
                            title="Edit Full Details"
                        >
                            <Pencil size={12} />
                        </button>
                    </div>
                )}

                {isEditModalOpen && (
                    <EditBookingModal
                        booking={booking}
                        onClose={() => setIsEditModalOpen(false)}
                    />
                )}
            </td>
            <td className="px-6 py-4">
                <span className={`text-[10px] font-bold uppercase tracking-wide px-2 py-1 rounded border ${booking.source === 'WEBSITE' ? 'bg-blue-50 text-blue-600 border-blue-100' :
                        'bg-purple-50 text-purple-600 border-purple-100'
                    }`}>
                    {booking.source === 'ADMIN' ? 'PORTAL' : (booking.source || 'WEBSITE')}
                </span>
            </td>
            <td className="px-6 py-4 text-center">
                {/* Report Status */}
                {booking.reportUrl ? (
                    <a href={booking.reportUrl} target="_blank" className="text-medical-teal-600 hover:underline text-xs font-bold flex items-center justify-center gap-1">
                        <FileText size={14} /> View
                    </a>
                ) : (
                    <span className="text-gray-400 text-xs italic">Pending</span>
                )}
            </td>
            <td className="px-6 py-4 text-right">
                <div className="flex justify-end items-center gap-2">
                    {isLoading && <Loader2 className="animate-spin text-gray-400" size={16} />}

                    {/* Status Actions */}
                    {booking.status === 'PENDING' && booking.type === 'HOME_COLLECTION' && (
                        <div className="flex flex-col gap-2 items-end">
                            {booking.requests && booking.requests.length > 0 && booking.requests.map((req: any) => (
                                <div key={req.id} className="flex items-center gap-2 bg-yellow-50 px-2 py-1 rounded border border-yellow-100 animate-pulse">
                                    <span className="text-[10px] text-yellow-800 font-medium">{req.collector.name} requested</span>
                                    <button
                                        onClick={async () => {
                                            setIsLoading(true);
                                            await approveAssignment(req.id, booking.id, req.collectorId);
                                            setIsLoading(false);
                                            router.refresh();
                                        }}
                                        className="text-[10px] bg-yellow-200 text-yellow-800 px-2 py-0.5 rounded hover:bg-yellow-300 font-bold"
                                    >
                                        Approve
                                    </button>
                                </div>
                            ))}

                            <select
                                onChange={(e) => handleAssign(e.target.value)}
                                className="bg-white border border-gray-300 text-gray-700 text-xs rounded-lg p-1.5 focus:ring-medical-teal-500 focus:border-medical-teal-500"
                                defaultValue=""
                            >
                                <option value="" disabled>Manual Assign</option>
                                {collectors.map(c => (
                                    <option key={c.id} value={c.id}>{c.name}</option>
                                ))}
                            </select>
                        </div>
                    )}

                    {booking.status === 'PENDING' && booking.type !== 'HOME_COLLECTION' && (
                        <button onClick={() => handleStatusUpdate('CONFIRMED')} className="text-medical-teal-600 hover:text-medical-teal-800 text-sm font-bold">Confirm</button>
                    )}

                    {booking.status === 'ASSIGNED' && (
                        <button onClick={() => handleStatusUpdate('COLLECTED')} className="text-indigo-600 hover:text-indigo-800 text-sm font-bold">Mark Collected</button>
                    )}

                    {booking.status === 'COLLECTED' && (
                        <button onClick={() => handleStatusUpdate('RECEIVED_AT_LAB')} className="text-purple-600 hover:text-purple-800 text-sm font-bold">Receive @ Lab</button>
                    )}

                    {booking.status === 'RECEIVED_AT_LAB' && (
                        <button onClick={() => handleStatusUpdate('PROCESSING')} className="text-yellow-600 hover:text-yellow-800 text-sm font-bold">Start Process</button>
                    )}

                    {booking.status === 'PROCESSING' && (
                        <button onClick={() => handleStatusUpdate('COMPLETED')} className="text-green-600 hover:text-green-800 text-sm font-bold">Publish Result</button>
                    )}
                </div>

                {isViewModalOpen && (
                    <BookingDetailsViewModal
                        booking={booking}
                        onClose={() => setIsViewModalOpen(false)}
                    />
                )}
            </td>
        </tr >
    );
}

"use client";

import { PieChart, BarChart2 } from "lucide-react";

export default function BookingStatusChart({
    total,
    pending,
    completed
}: {
    total: number;
    pending: number;
    completed: number;
}) {
    // Calculate Percentages
    // Prevent division by zero
    const safeTotal = total > 0 ? total : 1;

    const pendingPercent = Math.round((pending / safeTotal) * 100);
    const completedPercent = Math.round((completed / safeTotal) * 100);
    // Assuming the rest are "In Progress" or "Assigned" or similar if total > pending + completed
    // Or if total is exactly pending + completed + others.
    // For this chart let's focus on the asked metrics.

    // We can also have an "Others" category if math doesn't add up, logic dependent.
    // Let's assume Total = All bookings today.

    const maxVal = Math.max(total, 1);

    return (
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 flex flex-col h-full">
            <div className="flex items-center justify-between mb-6">
                <div>
                    <h3 className="font-bold text-gray-800 text-lg">Today's Activity</h3>
                    <p className="text-gray-500 text-sm">Status Breakdown</p>
                </div>
                <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                    <BarChart2 size={20} />
                </div>
            </div>

            <div className="space-y-6 flex-1 justify-center flex flex-col">
                {/* Total Bar */}
                <div className="space-y-2">
                    <div className="flex justify-between text-sm font-medium">
                        <span className="text-gray-600">Total Scheduled</span>
                        <span className="text-gray-900">{total} <span className="text-gray-400 text-xs font-normal ml-1">(100%)</span></span>
                    </div>
                    <div className="h-3 w-full bg-gray-100 rounded-full overflow-hidden">
                        <div className="h-full bg-blue-500 rounded-full" style={{ width: '100%' }}></div>
                    </div>
                </div>

                {/* Pending Bar */}
                <div className="space-y-2">
                    <div className="flex justify-between text-sm font-medium">
                        <span className="text-gray-600">Pending</span>
                        <span className="text-gray-900">{pending} <span className="text-gray-400 text-xs font-normal ml-1">({pendingPercent}%)</span></span>
                    </div>
                    <div className="h-3 w-full bg-gray-100 rounded-full overflow-hidden">
                        <div
                            className="h-full bg-orange-400 rounded-full transition-all duration-500"
                            style={{ width: `${pendingPercent}%` }}
                        ></div>
                    </div>
                </div>

                {/* Completed Bar */}
                <div className="space-y-2">
                    <div className="flex justify-between text-sm font-medium">
                        <span className="text-gray-600">Completed</span>
                        <span className="text-gray-900">{completed} <span className="text-gray-400 text-xs font-normal ml-1">({completedPercent}%)</span></span>
                    </div>
                    <div className="h-3 w-full bg-gray-100 rounded-full overflow-hidden">
                        <div
                            className="h-full bg-green-500 rounded-full transition-all duration-500"
                            style={{ width: `${completedPercent}%` }}
                        ></div>
                    </div>
                </div>
            </div>

            <div className="mt-6 pt-4 border-t border-gray-50 flex justify-between items-center text-xs text-gray-400">
                <span>Real-time updates</span>
                <span>{new Date().toLocaleDateString()}</span>
            </div>
        </div>
    );
}

"use client";

import { Users, Calendar, Clock, Activity, MapPin, FlaskConical, CheckCircle } from "lucide-react";
import { useState } from "react";
import StatsListModal from "./StatsListModal";

export default function DashboardStatsGrid({ stats }: { stats: any }) {
    const [modalConfig, setModalConfig] = useState<{ isOpen: boolean; type: string; title: string } | null>(null);

    const handleCardClick = (type: string, title: string) => {
        // Only allow clicking if it makes sense to show a list (e.g., skip 'Total Bookings' if it's too large or generic, or handle it differently)
        // User requested: Pending, Completed, Home Collection, Lab Visit
        if (['totalBookings', 'dailyVisitors', 'activeUsers'].includes(type)) return; // Skip these for now if not requested

        // Mapping types to server action keys
        const typeMap: Record<string, string> = {
            'pendingBookings': 'PENDING',
            'completedBookings': 'COMPLETED',
            'homeCollectionsToday': 'HOME_TODAY',
            'labVisitsToday': 'LAB_TODAY',
            'upcomingBookings': 'UPCOMING_3_DAYS',
            'testsToday': 'TESTS_TODAY',
            'fieldOfficers': 'FIELD_OFFICERS'
        };

        if (typeMap[type]) {
            setModalConfig({ isOpen: true, type: typeMap[type], title });
        }
    };

    return (
        <>
            <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-6">
                <StatCard
                    title="Tests Today"
                    value={stats.testsToday}
                    icon={Activity}
                    color="bg-purple-500"
                    trend="Total Scheduled"
                    onClick={() => handleCardClick('testsToday', "Today's Tests")}
                    isClickable
                />
                <StatCard
                    title="Home Collections"
                    value={stats.homeCollectionsToday}
                    icon={MapPin}
                    color="bg-indigo-500"
                    trend={`${stats.homeCollectionsPending} Pending / ${stats.homeCollectionsProcessing} Active`}
                    onClick={() => handleCardClick('homeCollectionsToday', "Today's Home Collections")}
                    isClickable
                />
                <StatCard
                    title="Lab Visits"
                    value={stats.labVisitsToday}
                    icon={FlaskConical}
                    color="bg-pink-500"
                    trend="Today"
                    onClick={() => handleCardClick('labVisitsToday', "Today's Lab Visits")}
                    isClickable
                />
                <StatCard
                    title="Pending"
                    value={stats.pendingBookings}
                    icon={Clock}
                    color="bg-orange-500"
                    trend="Needs action"
                    onClick={() => handleCardClick('pendingBookings', 'Pending Bookings')}
                    isClickable
                />
                <StatCard
                    title="Next 3 Days"
                    value={stats.upcomingCount}
                    icon={Calendar}
                    color="bg-cyan-500"
                    trend="Upcoming"
                    onClick={() => handleCardClick('upcomingBookings', "Upcoming Bookings (3 Days)")}
                    isClickable
                />
                <StatCard
                    title="Completed"
                    value={stats.completedBookings}
                    icon={CheckCircle}
                    color="bg-green-500"
                    trend="Total Reports"
                    onClick={() => handleCardClick('completedBookings', 'Completed Bookings')}
                    isClickable
                />
                <StatCard
                    title="Field Officers"
                    value={stats.totalCollectors || 0}
                    icon={Users}
                    color="bg-blue-600"
                    trend={`${stats.workingCollectors || 0} Active / ${stats.waitingCollectors || 0} Waiting`}
                    onClick={() => handleCardClick('fieldOfficers', 'Field Officer Status')}
                    isClickable
                />
            </div>

            {modalConfig && modalConfig.isOpen && (
                <StatsListModal
                    type={modalConfig.type}
                    title={modalConfig.title}
                    onClose={() => setModalConfig(null)}
                />
            )}
        </>
    );
}

function StatCard({ title, value, icon: Icon, color, trend, onClick, isClickable }: any) {
    return (
        <div
            onClick={onClick}
            className={`bg-white rounded-xl shadow-sm border border-gray-100 p-6 flex items-start justify-between transition-all ${isClickable ? 'cursor-pointer hover:shadow-md hover:border-medical-teal-200 active:scale-95' : ''}`}
        >
            <div>
                <p className="text-gray-500 text-sm font-medium mb-1">{title}</p>
                <h3 className="text-3xl font-bold text-gray-900 mb-2">{value}</h3>
                <p className={`text-xs font-medium ${trend.includes('+') ? 'text-green-600' : 'text-gray-500'}`}>{trend}</p>
            </div>
            <div className={`p-3 rounded-xl text-white ${color} shadow-lg shadow-gray-200`}>
                <Icon size={24} />
            </div>
        </div>
    )
}

'use client';

import { useState } from 'react';
import { createDoctor, updateDoctor, deleteDoctor } from '@/app/lib/doctor-actions';
import { X, Upload, Loader2, Trash2 } from 'lucide-react';
import Image from 'next/image';

interface DoctorFormModalProps {
    doctor?: any;
    onClose: () => void;
}

export default function DoctorFormModal({ doctor, onClose }: DoctorFormModalProps) {
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (formData: FormData) => {
        setIsLoading(true);
        if (doctor) {
            await updateDoctor(formData);
        } else {
            await createDoctor(formData);
        }
        setIsLoading(false);
        onClose();
    };

    const handleDelete = async () => {
        if (!confirm('Are you sure you want to delete this doctor?')) return;
        setIsLoading(true);
        await deleteDoctor(doctor.id);
        setIsLoading(false);
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in zoom-in duration-200">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-hidden flex flex-col">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                    <h3 className="font-bold text-gray-800">{doctor ? 'Edit Doctor' : 'Add New Doctor'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>

                <form action={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-4">
                    {doctor && <input type="hidden" name="id" value={doctor.id} />}

                    {/* Image URL Input (Simplified for now) */}
                    <div className="space-y-1">
                        <label className="text-xs font-bold text-gray-500 uppercase">Profile Image URL</label>
                        <div className="flex gap-2">
                            <input
                                type="text"
                                name="image"
                                defaultValue={doctor?.image || '/images/doctor-placeholder.jpg'}
                                placeholder="/images/doctor1.jpg or https://..."
                                className="input-field flex-1 border rounded-lg p-2 text-sm"
                            />
                        </div>
                        <p className="text-[10px] text-gray-400">Enter a URL or path to an image file.</p>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Name</label>
                            <input type="text" name="name" defaultValue={doctor?.name} required placeholder="Dr. John Doe" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Specialty</label>
                            <input type="text" name="specialty" defaultValue={doctor?.specialty} required placeholder="Cardiologist" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Education</label>
                            <input type="text" name="education" defaultValue={doctor?.education} required placeholder="MBBS, MD" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Experience</label>
                            <input type="text" name="experience" defaultValue={doctor?.experience} required placeholder="10+ Years" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Availability</label>
                            <input type="text" name="availability" defaultValue={doctor?.availability || "Sun-Fri / 10:00 AM - 4:00 PM"} placeholder="Sun-Fri / 10 AM - 4 PM" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Specialization Detail</label>
                            <input type="text" name="specializationDetails" defaultValue={doctor?.specializationDetails} placeholder="Expert in..." className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs font-bold text-gray-500 uppercase">Bio / Description</label>
                        <textarea name="bio" rows={4} defaultValue={doctor?.bio} required placeholder="Short biography..." className="input-field w-full border rounded-lg p-2 text-sm" />
                    </div>

                    <div className="pt-4 flex items-center justify-between gap-3">
                        {doctor && (
                            <button
                                type="button"
                                onClick={handleDelete}
                                disabled={isLoading}
                                className="text-red-500 hover:text-red-700 p-2 rounded hover:bg-red-50 transition-colors"
                            >
                                <Trash2 size={18} />
                            </button>
                        )}
                        <div className="flex gap-2 ml-auto">
                            <button
                                type="button"
                                onClick={onClose}
                                className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg text-sm font-medium transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="px-6 py-2 bg-black hover:bg-gray-800 text-white rounded-lg text-sm font-medium transition-all shadow-sm disabled:opacity-50 flex items-center gap-2"
                            >
                                {isLoading && <Loader2 size={14} className="animate-spin" />}
                                {doctor ? 'Update Doctor' : 'Add Doctor'}
                            </button>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import DoctorFormModal from './DoctorFormModal';
import { Plus, Pencil } from 'lucide-react';

export default function DoctorFormToggle({ doctor }: { doctor?: any }) {
    const [isOpen, setIsOpen] = useState(false);

    if (doctor) {
        return (
            <>
                <button
                    onClick={() => setIsOpen(true)}
                    className="bg-white text-gray-900 px-6 py-2 rounded-full font-bold hover:bg-gray-100 transition-colors flex items-center gap-2 transform translate-y-4 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 duration-300"
                >
                    <Pencil size={16} /> Edit Details
                </button>

                {isOpen && (
                    <DoctorFormModal
                        doctor={doctor}
                        onClose={() => setIsOpen(false)}
                    />
                )}
            </>
        );
    }

    return (
        <>
            <button
                onClick={() => setIsOpen(true)}
                className="bg-medical-teal-600 hover:bg-medical-teal-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors shadow-sm"
            >
                <Plus size={18} />
                Add New Doctor
            </button>

            {isOpen && (
                <DoctorFormModal
                    onClose={() => setIsOpen(false)}
                />
            )}
        </>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { createPackage, updatePackage, deletePackage } from '@/app/lib/package-actions';
import { getTests } from '@/app/lib/test-actions';
import { X, Loader2, Trash2, Check, Search } from 'lucide-react';

interface PackageFormModalProps {
    pkg?: any;
    onClose: () => void;
}

export default function PackageFormModal({ pkg, onClose }: PackageFormModalProps) {
    const [isLoading, setIsLoading] = useState(false);
    const [availableTests, setAvailableTests] = useState<any[]>([]);
    const [selectedTests, setSelectedTests] = useState<string[]>(pkg?.tests?.map((t: any) => t.id) || []);
    // Store discounts as percentage: { "testId": 20 } means 20% off
    const [testDiscounts, setTestDiscounts] = useState<Record<string, number>>({});
    const [searchTerm, setSearchTerm] = useState('');

    const filteredTests = availableTests.filter(test =>
        test.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        test.category.toLowerCase().includes(searchTerm.toLowerCase())
    );

    useEffect(() => {
        // Fetch available tests on mount
        getTests().then(tests => setAvailableTests(tests));
    }, []);

    const toggleTest = (testId: string) => {
        if (selectedTests.includes(testId)) {
            setSelectedTests(selectedTests.filter(id => id !== testId));
        } else {
            setSelectedTests([...selectedTests, testId]);
        }
    };

    const [discount, setDiscount] = useState<string>('');

    // Calculate total price of selected tests
    useEffect(() => {
        const total = selectedTests.reduce((sum, testId) => {
            const test = availableTests.find(t => t.id === testId);
            return sum + (test?.price || 0);
        }, 0);

        // Update Original Price field if it's not manually edited (or just show it for reference)
        // For simplicity, we'll auto-fill original price
        const originalPriceInput = document.querySelector('input[name="originalPrice"]') as HTMLInputElement;
        if (originalPriceInput) originalPriceInput.value = total.toString();

        // Calculate discounted price
        if (discount) {
            const disc = parseFloat(discount);
            if (!isNaN(disc)) {
                const finalPrice = Math.round(total * (1 - disc / 100));
                const priceInput = document.querySelector('input[name="price"]') as HTMLInputElement;
                if (priceInput) priceInput.value = finalPrice.toString();
            }
        }
    }, [selectedTests, availableTests, discount]);

    const handleDiscountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setDiscount(e.target.value);
    };

    const handleSubmit = async (formData: FormData) => {
        setIsLoading(true);
        if (pkg) {
            await updatePackage(formData, selectedTests);
        } else {
            await createPackage(formData, selectedTests);
        }
        setIsLoading(false);
        onClose();
    };

    const handleDelete = async () => {
        if (!confirm('Are you sure you want to delete this package?')) return;
        setIsLoading(true);
        await deletePackage(pkg.id);
        setIsLoading(false);
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in zoom-in duration-200">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl max-h-[90vh] overflow-hidden flex flex-col">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                    <h3 className="font-bold text-gray-800">{pkg ? 'Edit Package' : 'Create New Package'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>

                <form action={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-6">
                    {pkg && <input type="hidden" name="id" value={pkg.id} />}

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Package Name</label>
                            <input type="text" name="name" defaultValue={pkg?.name} required placeholder="e.g. Master Health Checkup" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Description</label>
                            <input type="text" name="description" defaultValue={pkg?.description} placeholder="Short description..." className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="grid grid-cols-3 gap-4 bg-gray-50 p-4 rounded-lg border border-gray-100 items-end">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Original Total (Rs.)</label>
                            <input type="number" name="originalPrice" defaultValue={pkg?.originalPrice} readOnly className="input-field w-full border rounded-lg p-2 text-sm bg-gray-100 text-gray-500" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-medical-teal-600 uppercase">Discount (%)</label>
                            <input
                                type="number"
                                placeholder="0"
                                value={discount}
                                onChange={handleDiscountChange}
                                className="input-field w-full border-2 border-medical-teal-100 rounded-lg p-2 text-sm focus:border-medical-teal-500 outline-none"
                            />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-900 uppercase">Final Price (Rs.)</label>
                            <input type="number" name="price" defaultValue={pkg?.price} required className="input-field w-full border-2 border-gray-200 rounded-lg p-2 text-sm font-bold text-gray-900" />
                        </div>
                    </div>

                    {/* Test Selection */}
                    <div className="space-y-2">
                        <label className="text-xs font-bold text-gray-500 uppercase flex justify-between">
                            <span>Includes Tests ({selectedTests.length})</span>
                            <span className="text-medical-teal-600 cursor-pointer" onClick={() => setSelectedTests(availableTests.map(t => t.id))}>Select All</span>
                        </label>

                        {/* Search Input */}
                        <div className="relative">
                            <input
                                type="text"
                                placeholder="Search tests..."
                                className="w-full border border-gray-200 rounded-lg p-2 text-sm pl-8 mb-2 focus:outline-none focus:border-medical-teal-500"
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                            <div className="absolute left-2.5 top-2.5 text-gray-400">
                                <Search size={14} />
                            </div>
                        </div>

                        <div className="border border-gray-200 rounded-lg p-4 max-h-60 overflow-y-auto bg-gray-50">
                            {filteredTests.length === 0 ? (
                                <p className="text-sm text-gray-500 text-center py-4">No tests found.</p>
                            ) : (
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                                    {filteredTests.map((test) => (
                                        <div
                                            key={test.id}
                                            onClick={() => toggleTest(test.id)}
                                            className={`flex items-center gap-3 p-2 rounded-md border cursor-pointer transition-all ${selectedTests.includes(test.id)
                                                ? 'bg-medical-teal-50 border-medical-teal-200 text-medical-teal-800'
                                                : 'bg-white border-gray-200 hover:border-gray-300'
                                                }`}
                                        >
                                            <div className={`w-4 h-4 rounded border flex items-center justify-center ${selectedTests.includes(test.id) ? 'bg-medical-teal-600 border-medical-teal-600' : 'border-gray-300'
                                                }`}>
                                                {selectedTests.includes(test.id) && <Check size={10} className="text-white" />}
                                            </div>
                                            <span className="text-sm font-medium truncate">{test.name}</span>
                                        </div>
                                    ))}
                                </div>
                            )}
                            <p className="text-xs text-gray-400">Search and select tests to add to the package.</p>
                        </div>

                        {/* Selected Tests Pricing Table */}
                        {selectedTests.length > 0 && (
                            <div className="space-y-2">
                                <label className="text-xs font-bold text-gray-500 uppercase">Selected Tests & Pricing</label>
                                <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
                                    <table className="w-full text-sm text-left">
                                        <thead className="bg-gray-50 text-gray-500 font-medium border-b border-gray-100">
                                            <tr>
                                                <th className="p-3">Test Name</th>
                                                <th className="p-3 text-right">Base Price</th>
                                                <th className="p-3 text-center w-24">Discount %</th>
                                                <th className="p-3 text-right">Final Price</th>
                                                <th className="p-3 w-10"></th>
                                            </tr>
                                        </thead>
                                        <tbody className="divide-y divide-gray-50">
                                            {selectedTests.map(testId => {
                                                const test = availableTests.find(t => t.id === testId);
                                                if (!test) return null;
                                                const discount = testDiscounts[testId] || 0;
                                                const finalPrice = Math.round(test.price * (1 - discount / 100));

                                                return (
                                                    <tr key={testId}>
                                                        <td className="p-3">{test.name}</td>
                                                        <td className="p-3 text-right text-gray-500">Rs. {test.price}</td>
                                                        <td className="p-3">
                                                            <input
                                                                type="number"
                                                                min="0"
                                                                max="100"
                                                                placeholder="0"
                                                                value={testDiscounts[testId] || ''}
                                                                onChange={(e) => handleTestDiscountChange(testId, e.target.value)}
                                                                className="w-full border rounded p-1 text-center text-xs"
                                                            />
                                                        </td>
                                                        <td className="p-3 text-right font-bold text-gray-800">Rs. {finalPrice}</td>
                                                        <td className="p-3 text-center">
                                                            <button
                                                                type="button"
                                                                onClick={() => toggleTest(testId)}
                                                                className="text-red-400 hover:text-red-600"
                                                            >
                                                                <X size={14} />
                                                            </button>
                                                        </td>
                                                    </tr>
                                                );
                                            })}
                                        </tbody>
                                    </table>
                                </div>
                            </div>
                        )}

                        <div className="pt-4 flex items-center justify-between gap-3 border-t border-gray-100 mt-4">
                            {pkg && (
                                <button
                                    type="button"
                                    onClick={handleDelete}
                                    disabled={isLoading}
                                    className="text-red-500 hover:text-red-700 p-2 rounded hover:bg-red-50 transition-colors"
                                >
                                    <Trash2 size={18} />
                                </button>
                            )}
                            <div className="flex gap-2 ml-auto">
                                <button
                                    type="button"
                                    onClick={onClose}
                                    className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg text-sm font-medium transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="px-6 py-2 bg-black hover:bg-gray-800 text-white rounded-lg text-sm font-medium transition-all shadow-sm disabled:opacity-50 flex items-center gap-2"
                                >
                                    {isLoading && <Loader2 size={14} className="animate-spin" />}
                                    {pkg ? 'Update Package' : 'Create Package'}
                                </button>
                            </div>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import PackageFormModal from './PackageFormModal';
import { Plus, Pencil } from 'lucide-react';

export default function PackageFormToggle({ pkg }: { pkg?: any }) {
    const [isOpen, setIsOpen] = useState(false);

    if (pkg) {
        return (
            <>
                <button
                    onClick={() => setIsOpen(true)}
                    className="text-white bg-white/20 hover:bg-white/30 p-2 rounded-full transition-colors backdrop-blur-sm"
                    title="Edit Package"
                >
                    <Pencil size={16} />
                </button>

                {isOpen && (
                    <PackageFormModal
                        pkg={pkg}
                        onClose={() => setIsOpen(false)}
                    />
                )}
            </>
        );
    }

    return (
        <>
            <button
                onClick={() => setIsOpen(true)}
                className="bg-medical-teal-600 hover:bg-medical-teal-700 text-white px-4 py-2 rounded-lg font-bold flex items-center gap-2 transition-colors shadow-sm whitespace-nowrap"
            >
                <Plus size={18} />
                Create Package
            </button>

            {isOpen && (
                <PackageFormModal
                    onClose={() => setIsOpen(false)}
                />
            )}
        </>
    );
}

"use client";

import { useState } from "react";
import BookingDetailsViewModal from "./BookingDetailsViewModal";
import { assignBooking, updateBookingStatus } from "@/app/lib/booking-actions";
import { useRouter } from "next/navigation";

export default function RecentBookingsTable({ bookings, collectors }: { bookings: any[]; collectors: any[] }) {
    const [selectedBooking, setSelectedBooking] = useState<any>(null);
    const router = useRouter();

    const handleAssign = async (bookingId: string, collectorId: string) => {
        const formData = new FormData();
        formData.append("bookingId", bookingId);
        formData.append("collectorId", collectorId);
        await assignBooking(formData);
        router.refresh();
        setSelectedBooking(null); // Close modal on success
    };

    const handleStatusUpdate = async (bookingId: string, status: string) => {
        const formData = new FormData();
        formData.append("bookingId", bookingId);
        formData.append("status", status);
        await updateBookingStatus(formData);
        router.refresh();
        setSelectedBooking(null);
    };

    return (
        <>
            <div className="overflow-x-auto">
                <table className="w-full text-left">
                    <thead>
                        <tr className="border-b border-gray-200 text-gray-500 text-sm uppercase">
                            <th className="py-3 font-medium">Patient</th>
                            <th className="py-3 font-medium">Test</th>
                            <th className="py-3 font-medium">Date</th>
                            <th className="py-3 font-medium">Status</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-100">
                        {bookings.length === 0 ? (
                            <tr>
                                <td colSpan={4} className="py-8 text-center text-gray-500">No bookings found</td>
                            </tr>
                        ) : (
                            bookings.map((booking: any) => (
                                <tr
                                    key={booking.id}
                                    className="hover:bg-gray-50 cursor-pointer transition-colors"
                                    onClick={() => setSelectedBooking(booking)}
                                >
                                    <td className="py-4 font-medium text-gray-900">{booking.patientName}</td>
                                    <td className="py-4 text-gray-600">{booking.testType}</td>
                                    <td className="py-4 text-gray-600">{new Date(booking.date).toLocaleDateString()}</td>
                                    <td className="py-4">
                                        <span className={`px-3 py-1 rounded-full text-xs font-bold ${booking.status === 'PENDING' ? 'bg-orange-100 text-orange-700' :
                                            booking.status === 'CONFIRMED' ? 'bg-green-100 text-green-700' :
                                                'bg-gray-100 text-gray-600'
                                            }`}>
                                            {booking.status}
                                        </span>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            <BookingDetailsViewModal
                booking={selectedBooking}
                collectors={collectors}
                onClose={() => setSelectedBooking(null)}
                onAssign={handleAssign}
                onStatusUpdate={handleStatusUpdate}
            />
        </>
    );
}

"use client";

import { X, Calendar, User, MapPin, FlaskConical, Clock } from "lucide-react";
import { useEffect, useState } from "react";
import { getBookingListByType } from "@/app/lib/booking-actions";

export default function StatsListModal({ type, title, onClose }: { type: string; title: string; onClose: () => void }) {
    const [bookings, setBookings] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchList() {
            setLoading(true);
            const data = await getBookingListByType(type);
            setBookings(data);
            setLoading(false);
        }
        fetchList();
    }, [type]);

    return (
        <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in duration-200">
            <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl max-h-[80vh] flex flex-col overflow-hidden">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                    <h3 className="font-bold text-gray-800 flex items-center gap-2">
                        {title}
                        <span className="bg-gray-200 text-gray-600 text-xs px-2 py-0.5 rounded-full">{bookings.length}</span>
                    </h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600 p-1 rounded-full hover:bg-gray-200 transition-colors">
                        <X size={20} />
                    </button>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {loading ? (
                        <div className="flex justify-center py-8 text-medical-teal-600">
                            <Clock className="animate-spin" size={24} />
                        </div>
                    ) : bookings.length === 0 ? (
                        <div className="text-center py-8 text-gray-400 text-sm">
                            No records found for this category.
                        </div>
                    ) : (
                        bookings.map((item: any) => (
                            <div key={item.id} className="bg-white border border-gray-100 rounded-lg p-3 hover:shadow-md transition-shadow flex justify-between items-center group">
                                {type === 'FIELD_OFFICERS' ? (
                                    // Field Officer Render
                                    <>
                                        <div className="space-y-1">
                                            <div className="flex items-center gap-2">
                                                <User size={16} className="text-blue-600" />
                                                <span className="font-bold text-gray-900 text-sm">{item.name}</span>
                                            </div>
                                            <div className="text-xs text-gray-500">
                                                {item.email}
                                            </div>
                                            {item.currentTask && (
                                                <div className="flex items-center gap-1 text-xs text-gray-500 mt-1 bg-gray-50 p-1.5 rounded">
                                                    <span className="font-semibold text-gray-700">Current Task:</span>
                                                    <span>{item.currentTask.patientName}</span>
                                                    <span className="bg-blue-100 text-blue-700 px-1 rounded text-[10px]">{item.currentTask.status}</span>
                                                </div>
                                            )}
                                        </div>
                                        <div className="text-right">
                                            <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide ${item.status === 'WORKING' ? 'bg-green-100 text-green-700' : 'bg-yellow-100 text-yellow-700'
                                                }`}>
                                                {item.status === 'WORKING' ? 'Working' : 'Waiting'}
                                            </span>
                                        </div>
                                    </>
                                ) : (
                                    // Regular Booking Render
                                    <>
                                        <div className="space-y-1">
                                            <div className="flex items-center gap-2">
                                                <span className="font-bold text-gray-900 text-sm">{item.patientName}</span>
                                                <span className="text-xs text-gray-400 font-mono">#{item.id.slice(-5).toUpperCase()}</span>
                                            </div>
                                            <div className="flex items-center gap-3 text-xs text-gray-500">
                                                <span className="flex items-center gap-1">
                                                    <Calendar size={12} /> {new Date(item.date).toLocaleDateString()}
                                                </span>
                                                <span className="flex items-center gap-1">
                                                    <FlaskConical size={12} /> {item.testType}
                                                </span>
                                                <span className={`flex items-center gap-1 font-semibold ${item.type === 'HOME_COLLECTION' ? 'text-indigo-600' : 'text-pink-600'}`}>
                                                    {item.type === 'HOME_COLLECTION' ? 'Home' : 'Lab'}
                                                </span>
                                            </div>
                                            {item.address && (
                                                <div className="flex items-center gap-1 text-xs text-gray-500 max-w-xs truncate">
                                                    <MapPin size={12} className="shrink-0" /> {item.address}
                                                </div>
                                            )}
                                        </div>
                                        <div className="text-right">
                                            <span className={`inline-block px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide ${item.status === 'PENDING' ? 'bg-orange-100 text-orange-700' :
                                                item.status === 'COMPLETED' ? 'bg-green-100 text-green-700' :
                                                    'bg-blue-100 text-blue-700'
                                                }`}>
                                                {item.status}
                                            </span>
                                        </div>
                                    </>
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>
        </div>
    );
}

'use client';

import { useState } from 'react';
import { createTest, updateTest, deleteTest } from '@/app/lib/test-actions';
import { X, Loader2, Trash2 } from 'lucide-react';

interface TestFormModalProps {
    test?: any;
    onClose: () => void;
}

export default function TestFormModal({ test, onClose }: TestFormModalProps) {
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (formData: FormData) => {
        setIsLoading(true);
        if (test) {
            await updateTest(formData);
        } else {
            await createTest(formData);
        }
        setIsLoading(false);
        onClose();
    };

    const handleDelete = async () => {
        if (!confirm('Are you sure you want to delete this test?')) return;
        setIsLoading(true);
        await deleteTest(test.id);
        setIsLoading(false);
        onClose();
    };

    return (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4 backdrop-blur-sm animate-in fade-in zoom-in duration-200">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-hidden flex flex-col">
                <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                    <h3 className="font-bold text-gray-800">{test ? 'Edit Test' : 'Add New Test'}</h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
                        <X size={20} />
                    </button>
                </div>

                <form action={handleSubmit} className="flex-1 overflow-y-auto p-6 space-y-4">
                    {test && <input type="hidden" name="id" value={test.id} />}

                    <div className="space-y-1">
                        <label className="text-xs font-bold text-gray-500 uppercase">Test Name</label>
                        <input type="text" name="name" defaultValue={test?.name} required placeholder="e.g. CBC (Complete Blood Count)" className="input-field w-full border rounded-lg p-2 text-sm" />
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Category</label>
                            <select name="category" defaultValue={test?.category || "Pathology"} className="input-field w-full border rounded-lg p-2 text-sm bg-white">
                                <option value="Pathology">Pathology</option>
                                <option value="Biochemistry">Biochemistry</option>
                                <option value="Hematology">Hematology</option>
                                <option value="Microbiology">Microbiology</option>
                                <option value="Serology">Serology</option>
                                <option value="Hormones">Hormones</option>
                                <option value="Radiology">Radiology</option>
                                <option value="Other">Other</option>
                            </select>
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Turn Around Time (TAT)</label>
                            <input type="text" name="tat" defaultValue={test?.tat} placeholder="e.g. 24 Hours" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Price (Rs.)</label>
                            <input type="number" name="price" defaultValue={test?.price} required placeholder="1000" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                        <div className="space-y-1">
                            <label className="text-xs font-bold text-gray-500 uppercase">Discount Price (Optional)</label>
                            <input type="number" name="discountPrice" defaultValue={test?.discountPrice} placeholder="800" className="input-field w-full border rounded-lg p-2 text-sm" />
                        </div>
                    </div>

                    <div className="space-y-1">
                        <label className="text-xs font-bold text-gray-500 uppercase">Description</label>
                        <textarea name="description" rows={3} defaultValue={test?.description} placeholder="Brief details about the test..." className="input-field w-full border rounded-lg p-2 text-sm" />
                    </div>

                    <div className="pt-4 flex items-center justify-between gap-3">
                        {test && (
                            <button
                                type="button"
                                onClick={handleDelete}
                                disabled={isLoading}
                                className="text-red-500 hover:text-red-700 p-2 rounded hover:bg-red-50 transition-colors"
                            >
                                <Trash2 size={18} />
                            </button>
                        )}
                        <div className="flex gap-2 ml-auto">
                            <button
                                type="button"
                                onClick={onClose}
                                className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded-lg text-sm font-medium transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="px-6 py-2 bg-black hover:bg-gray-800 text-white rounded-lg text-sm font-medium transition-all shadow-sm disabled:opacity-50 flex items-center gap-2"
                            >
                                {isLoading && <Loader2 size={14} className="animate-spin" />}
                                {test ? 'Update Test' : 'Add Test'}
                            </button>
                        </div>
                    </div>
                </form>
            </div>
        </div>
    );
}

