'use client';

import { HandCoins, CheckCircle2, Clock, CalendarCheck, PackageSearch } from 'lucide-react';
import React, { useState } from 'react';
import CollectorStatsModal from './CollectorStatsModal';
import { getCollectorBookingsByCategory } from '@/app/lib/booking-actions';

interface CollectorStatsProps {
    stats: {
        lifetimeCollected: number;
        todayCollection: number;
        assigned: number;
        completed: number;
        pending: number;
    }
}

export default function CollectorStats({ stats }: CollectorStatsProps) {
    const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
    const [modalData, setModalData] = useState<any[]>([]);
    const [loading, setLoading] = useState(false);
    const [isModalOpen, setIsModalOpen] = useState(false);

    const handleStatClick = async (category: string, title: string) => {
        setSelectedCategory(title);
        setIsModalOpen(true);
        setLoading(true);
        try {
            const data = await getCollectorBookingsByCategory(category);
            setModalData(data);
        } catch (error) {
            console.error("Failed to fetch details", error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                <div
                    onClick={() => handleStatClick('LIFETIME', 'Lifetime Collected')}
                    className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-md transition-shadow group"
                >
                    <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                        <HandCoins size={20} />
                    </div>
                    <p className="text-2xl font-bold text-gray-800">{stats.lifetimeCollected}</p>
                    <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Lifetime Collected</p>
                </div>

                <div
                    onClick={() => handleStatClick('TODAY', 'Collected Today')}
                    className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-md transition-shadow group"
                >
                    <div className="w-10 h-10 bg-green-50 text-green-600 rounded-full flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                        <CalendarCheck size={20} />
                    </div>
                    <p className="text-2xl font-bold text-gray-800">{stats.todayCollection}</p>
                    <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Collected Today</p>
                </div>

                <div
                    onClick={() => handleStatClick('ASSIGNED', 'Assigned Bookings')}
                    className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-md transition-shadow group"
                >
                    <div className="w-10 h-10 bg-orange-50 text-orange-600 rounded-full flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                        <Clock size={20} />
                    </div>
                    <p className="text-2xl font-bold text-gray-800">{stats.assigned}</p>
                    <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Assigned</p>
                </div>

                <div
                    onClick={() => handleStatClick('COMPLETED', 'Completed Bookings')}
                    className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-md transition-shadow group"
                >
                    <div className="w-10 h-10 bg-purple-50 text-purple-600 rounded-full flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                        <CheckCircle2 size={20} />
                    </div>
                    <p className="text-2xl font-bold text-gray-800">{stats.completed}</p>
                    <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Completed</p>
                </div>

                <div
                    onClick={() => handleStatClick('PENDING', 'Available (Pending)')}
                    className="bg-white p-4 rounded-xl border border-gray-100 shadow-sm flex flex-col items-center justify-center text-center cursor-pointer hover:shadow-md transition-shadow group"
                >
                    <div className="w-10 h-10 bg-gray-50 text-gray-600 rounded-full flex items-center justify-center mb-2 group-hover:scale-110 transition-transform">
                        <PackageSearch size={20} />
                    </div>
                    <p className="text-2xl font-bold text-gray-800">{stats.pending}</p>
                    <p className="text-xs text-gray-500 font-medium uppercase tracking-wide">Available (Pending)</p>
                </div>
            </div>

            <CollectorStatsModal
                isOpen={isModalOpen}
                onClose={() => setIsModalOpen(false)}
                title={selectedCategory || ''}
                bookings={modalData}
                loading={loading}
                category={selectedCategory === 'Available (Pending)' ? 'PENDING' : ''} // Map title to category safely or use state
            />
        </>
    );
}

'use client';

import { X, Calendar, User, FileText, MapPin, Eye, CheckCircle } from 'lucide-react';
import { format } from 'date-fns';
import { requestAssignment } from '@/app/lib/booking-actions';
import { useState } from 'react';
import BookingDetailsViewModal from '@/components/admin/BookingDetailsViewModal';

interface CollectorStatsModalProps {
    isOpen: boolean;
    onClose: () => void;
    title: string;
    bookings: any[];
    loading: boolean;
    category: string; // Add category to know when to show actions
}

export default function CollectorStatsModal({ isOpen, onClose, title, bookings, loading, category }: CollectorStatsModalProps) {
    const [requesting, setRequesting] = useState<string | null>(null);
    const [selectedBooking, setSelectedBooking] = useState<any | null>(null); // State for detailed view

    if (!isOpen) return null;

    const handleApply = async (bookingId: string) => {
        setRequesting(bookingId);
        try {
            const res = await requestAssignment(bookingId);
            if (res.message.includes('Success')) {
                alert(res.message);
                onClose(); // Close modal to refresh data or just let user see
            } else {
                alert(res.message);
            }
        } catch (error) {
            console.error("Request failed", error);
            alert("Failed to request assignment");
        } finally {
            setRequesting(null);
        }
    };

    const handleView = (booking: any) => {
        setSelectedBooking(booking);
    };

    return (
        <>
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-in fade-in">
                <div className="bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[80vh] flex flex-col overflow-hidden animate-in zoom-in-95 duration-200">
                    <div className="p-4 border-b border-gray-100 flex justify-between items-center bg-gray-50">
                        <h3 className="text-lg font-bold text-gray-800">{title}</h3>
                        <button onClick={onClose} className="text-gray-400 hover:text-gray-600 transition-colors">
                            <X size={20} />
                        </button>
                    </div>

                    <div className="flex-1 overflow-y-auto p-4 space-y-3">
                        {loading ? (
                            <div className="flex justify-center py-10">
                                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-medical-teal-600"></div>
                            </div>
                        ) : bookings.length === 0 ? (
                            <div className="text-center py-10 text-gray-500">
                                No bookings found in this category.
                            </div>
                        ) : (
                            bookings.map((booking) => (
                                <div key={booking.id} className="border border-gray-100 rounded-lg p-3 hover:bg-gray-50 transition-colors">
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="flex items-center gap-2">
                                            <User size={16} className="text-medical-teal-600" />
                                            <span className="font-semibold text-gray-800">{booking.patientName}</span>
                                        </div>
                                        <span className={`text-xs px-2 py-1 rounded-full font-medium ${booking.status === 'COMPLETED' ? 'bg-green-100 text-green-700' :
                                                booking.status === 'PENDING' ? 'bg-yellow-100 text-yellow-700' :
                                                    booking.status === 'ASSIGNED' ? 'bg-blue-100 text-blue-700' :
                                                        'bg-gray-100 text-gray-700'
                                            }`}>
                                            {booking.status.replace(/_/g, ' ')}
                                        </span>
                                    </div>
                                    <div className="grid grid-cols-2 gap-2 text-sm text-gray-600 mb-3">
                                        <div className="flex items-center gap-2">
                                            <FileText size={14} className="text-gray-400" />
                                            <span>{booking.testType}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Calendar size={14} className="text-gray-400" />
                                            <span>{format(new Date(booking.date), 'PP')}</span>
                                        </div>
                                        {booking.address && (
                                            <div className="col-span-2 flex items-center gap-2">
                                                <MapPin size={14} className="text-gray-400" />
                                                <span className="truncate">{booking.address}</span>
                                            </div>
                                        )}
                                    </div>

                                    {/* Actions for Available Bookings */}
                                    {category === 'PENDING' && (
                                        <div className="flex gap-2 pt-2 border-t border-gray-100">
                                            <button
                                                onClick={() => handleView(booking)}
                                                className="flex-1 flex items-center justify-center gap-2 py-1.5 border border-gray-200 rounded text-sm text-gray-600 hover:bg-gray-50"
                                            >
                                                <Eye size={14} /> View
                                            </button>
                                            <button
                                                onClick={() => handleApply(booking.id)}
                                                disabled={requesting === booking.id || booking.requests?.some((r: any) => r.status === 'PENDING')}
                                                className="flex-1 flex items-center justify-center gap-2 py-1.5 bg-medical-teal-600 text-white rounded text-sm hover:bg-medical-teal-700 disabled:opacity-50"
                                            >
                                                {requesting === booking.id ? 'Requesting...' : (
                                                    booking.requests?.some((r: any) => r.status === 'PENDING') ? 'Requested' : 'Apply Request'
                                                )}
                                            </button>
                                        </div>
                                    )}
                                </div>
                            ))
                        )}
                    </div>

                    <div className="p-4 border-t border-gray-100 bg-gray-50 flex justify-end">
                        <button onClick={onClose} className="px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium hover:bg-gray-50">
                            Close
                        </button>
                    </div>
                </div>
            </div>

            {/* Nested Detailed View Modal */}
            {selectedBooking && (
                <BookingDetailsViewModal
                    booking={selectedBooking}
                    onClose={() => setSelectedBooking(null)}
                />
            )}
        </>
    );
}

